<?php
declare(strict_types=1);
require_once __DIR__ . '/config/product_step12.php';
$error=null;$order=null;$items=[];$payments=[];$events=[];$ledger=null;$ctx=[];$orderId=(int)($_GET['order']??0);
try{
    if($orderId<=0)throw new RuntimeException('Choose a valid Product Sale order.');
    $pdo=business_db();product_step12_ensure($pdo);$ctx=product_step12_context($pdo);$orgId=(int)$ctx['organization_id'];
    $stmt=$pdo->prepare("SELECT o.*,m.full_name member_name,m.mobile member_mobile,l.quote_id,q.quote_code,q.customer_name,q.pricing_tier_code,q.payable_amount product_payable,q.delivery_charge,q.grand_total
        FROM orders o LEFT JOIN members m ON m.id=o.member_id AND m.organization_id=o.organization_id LEFT JOIN product_quote_order_links l ON l.organization_id=o.organization_id AND l.order_id=o.id LEFT JOIN product_quotes q ON q.id=l.quote_id AND q.organization_id=o.organization_id
        WHERE o.organization_id=? AND o.id=? AND o.order_type='product_sale' LIMIT 1");$stmt->execute([$orgId,$orderId]);$order=$stmt->fetch();if(!$order)throw new RuntimeException('Product Sale order was not found.');
    $ledger=product_step12_ledger($pdo,$orgId,$orderId);if($ledger)$paymentState=product_step12_sync_payment_status($pdo,$orderId);else $paymentState=['paid'=>0,'due'=>(float)$order['net_amount'],'outstanding'=>(float)$order['net_amount'],'status'=>'unpaid'];
    $stmt=$pdo->prepare("SELECT poi.*,cv.source_reference cost_source,cv.effective_from cost_effective FROM product_order_items poi LEFT JOIN product_cost_versions cv ON cv.id=poi.cost_version_id AND cv.organization_id=poi.organization_id WHERE poi.organization_id=? AND poi.order_id=? ORDER BY poi.id");$stmt->execute([$orgId,$orderId]);$items=$stmt->fetchAll();
    $stmt=$pdo->prepare("SELECT * FROM product_sale_payments WHERE organization_id=? AND order_id=? ORDER BY payment_date,id");$stmt->execute([$orgId,$orderId]);$payments=$stmt->fetchAll();
    if($ledger){$stmt=$pdo->prepare("SELECT * FROM product_sale_lifecycle_events WHERE organization_id=? AND sale_ledger_id=? ORDER BY id DESC");$stmt->execute([$orgId,(int)$ledger['id']]);$events=$stmt->fetchAll();}
}catch(Throwable $e){$error=$e->getMessage();$paymentState=['paid'=>0,'due'=>0,'outstanding'=>0,'status'=>'unpaid'];}
function psd_money(mixed $v):string{return '₹'.number_format((float)$v,2,'.',',');}function psd_num(mixed $v):string{$x=number_format((float)$v,3,'.','');return rtrim(rtrim($x,'0'),'.');}
?>
