<main class="os-main"><section class="os-hero pp-hero"><div class="os-kicker">STEP 12F • SALE 360° TRACE</div><h1><?= $error?'Product Sale review required':'Business OS Order #'.(int)$order['id'] ?></h1><p>Quote snapshot, member/customer identity, product lines, exact cost coverage, payment collection, lifecycle events and raw Business OS source trace remain connected here.</p><?php if(!$error):?><div class="os-status-row"><span class="os-chip <?= ($ledger['sale_status']??'active')==='active'?'good':'' ?>"><?= product_h(strtoupper((string)($ledger['sale_status']??'ACTIVE'))) ?></span><span class="os-chip"><?= product_h(strtoupper($paymentState['status'])) ?> • <?= psd_money($paymentState['paid']) ?> paid</span><span class="os-chip">Cost <?= product_h(strtoupper((string)($ledger['cost_status']??'DEFERRED'))) ?></span><span class="os-chip"><?= product_h(psd_num($order['volume_points'])) ?> VP</span></div><?php endif;?></section>
<?php if($error):?><div class="pp-alert bad"><strong>Sale diagnostic:</strong> <?= product_h($error) ?></div><?php else:?><section class="pp-grid" style="margin-top:14px"><article class="os-card pp-span-8"><div class="os-title-row"><div><h2><?= product_h($order['quote_code']?:'Product Sale') ?></h2><p><?= product_h((string)$order['order_date']) ?> • <?= product_h($order['pricing_tier_code']?:'—') ?></p></div><span class="pp-badge">ORDER #<?= (int)$order['id'] ?></span></div><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Stock</th><th>Product</th><th>Qty</th><th>Unit Price</th><th>VP</th><th>Unit Cost</th><th>Line Profit</th><th>Profit State</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><b><?= product_h($i['stock_no']) ?></b></td><td><?= product_h($i['product_name_snapshot']) ?></td><td><?= product_h(psd_num($i['quantity'])) ?></td><td><?= psd_money($i['unit_price']) ?></td><td><?= product_h(psd_num($i['line_vp'])) ?></td><td><?= $i['unit_cost']===null?'—':psd_money($i['unit_cost']) ?><?= $i['cost_source']?'<small>'.product_h($i['cost_source']).'</small>':'' ?></td><td><?= $i['line_profit']===null?'—':psd_money($i['line_profit']) ?></td><td><span class="pp-badge"><?= product_h(strtoupper((string)$i['profit_status'])) ?></span></td></tr><?php endforeach;?><?php if(!$items):?><tr><td colspan="8">No line item snapshots found.</td></tr><?php endif;?></tbody></table></div></article>
<aside class="os-card pp-span-4"><h2>Business Mapping</h2><div class="pp-source"><b>Customer snapshot</b><span><?= product_h($order['customer_name']?:'—') ?></span></div><div class="pp-source"><b>Verified member</b><span><?= product_h($order['member_name']?:'Not linked') ?><?= $order['member_id']?' #'.(int)$order['member_id']:'' ?></span></div><div class="pp-source"><b>Gross</b><span><?= psd_money($order['gross_amount']) ?></span></div><div class="pp-source"><b>Discount/Saving</b><span><?= psd_money($order['discount_amount']) ?></span></div><div class="pp-source"><b>Net Revenue</b><span><?= psd_money($order['net_amount']) ?></span></div><div class="pp-source"><b>Paid / Outstanding</b><span><?= psd_money($paymentState['paid']) ?> / <?= psd_money($paymentState['outstanding']) ?></span></div><div class="pp-source"><b>Cost Status</b><span><?= product_h(strtoupper((string)($ledger['cost_status']??'deferred'))) ?></span></div><div class="pp-source"><b>Verified Profit</b><span><?= ($ledger['profit_total']??null)===null?'—':psd_money($ledger['profit_total']) ?></span></div><div class="pp-source"><b>Raw Source ID</b><span>#<?= (int)$order['source_record_id'] ?></span></div><div class="pp-actions"><a href="product_payments.php?order=<?= (int)$order['id'] ?>">Payments →</a><a href="product_cost_center.php">Cost Basis →</a></div></aside></section>
<section class="pp-grid"><article class="os-card pp-span-6"><h2>Payment History</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Date</th><th>Amount</th><th>Method</th><th>Status</th></tr></thead><tbody><?php foreach($payments as $p):?><tr><td><?= product_h($p['payment_date']) ?></td><td><?= psd_money($p['amount']) ?></td><td><?= product_h(strtoupper($p['payment_method'])) ?><?= $p['reference_no']?'<small>'.product_h($p['reference_no']).'</small>':'' ?></td><td><?= product_h(strtoupper($p['status'])) ?></td></tr><?php endforeach;?><?php if(!$payments):?><tr><td colspan="4">No payments recorded yet.</td></tr><?php endif;?></tbody></table></div></article><article class="os-card pp-span-6"><h2>Lifecycle Timeline</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Event</th><th>Reason</th><th>Time</th></tr></thead><tbody><?php foreach($events as $e):?><tr><td><b><?= product_h(ucwords(str_replace('_',' ',$e['event_type']))) ?></b></td><td><?= product_h($e['reason']?:'—') ?></td><td><?= product_h($e['created_at']) ?></td></tr><?php endforeach;?><?php if(!$events):?><tr><td colspan="3">No lifecycle events found.</td></tr><?php endif;?></tbody></table></div></article></section>
<div class="os-footer-note"><strong>Trace policy:</strong> cancellation never deletes this sale. It changes active business effect while preserving quote, raw source, order, product lines, payments and lifecycle evidence.</div><?php endif;?></main></div></body></html>